// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 warpTime) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1000 ether);
        warpTime = bound(warpTime, 1, block.timestamp);
        vm.warp(warpTime);

        vm.deal(actor, amount);
        uint256 before = __invmut_c_Acc_balance(actor);

        vm.prank(actor);
        c.Put{value: amount}(0);

        assertEq(__invmut_c_Acc_balance(actor), before + amount);
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
}
